import React, { useEffect, useRef } from "react";
import { formatTime, getMessageUrl, linkifyAndEmojify } from "../../../js/Chat/PrivateChat.helpers.js";

/**
 * MessageMenu: flutuante (3 pontos)
 */
export function MessageMenu({ msg, onEdit, onDeleteForMe, onDeleteForAll, openMenuId, setOpenMenuId }) {
  const ref = useRef(null);

  useEffect(() => {
    function onDocClick(e) {
      if (ref.current && !ref.current.contains(e.target)) {
        setOpenMenuId(null);
      }
    }
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, [setOpenMenuId]);

  if (msg.from !== msg.currentUserId) return null;

  return (
    <div ref={ref} style={{ position: "absolute", top: -6, right: -6, zIndex: 60 }}>
      <button
        onClick={() => setOpenMenuId(openMenuId === msg.id ? null : msg.id)}
        style={{ background: "transparent", border: "none", cursor: "pointer", fontSize: 16 }}
        aria-label="menu"
      >
        ⋮
      </button>

      {openMenuId === msg.id && (
        <div className="message-menu" style={{
          position: "absolute",
          right: 0,
          top: 26,
          background: "#fff",
          border: "1px solid #eee",
          borderRadius: 8,
          boxShadow: "0 6px 14px rgba(0,0,0,0.10)",
          minWidth: 140
        }}>
          <div className="menu-item" onClick={() => { setOpenMenuId(null); onEdit(msg); }}>Editar</div>
          <div className="menu-item" onClick={() => { setOpenMenuId(null); onDeleteForMe(msg); }}>Excluir para mim</div>
          <div className="menu-item" onClick={() => { setOpenMenuId(null); onDeleteForAll(msg); }}>Excluir para todos</div>
        </div>
      )}
    </div>
  );
}

/**
 * MessageBubble
 */
export function MessageBubble({ m, isMe, sender, currentUserId, openMenuId, setOpenMenuId, onEdit, onDeleteForMe, onDeleteForAll }) {
  const url = getMessageUrl(m.url);
  const overflowStyle = { maxWidth: 480, wordBreak: "break-word" };

  return (
    <div className={`msg-wrap ${isMe ? "msg-me" : "msg-other"}`}
      style={{ display: "flex", justifyContent: isMe ? "flex-end" : "flex-start", marginBottom: 10, position: "relative" }}
    >
      {!isMe && (
        <img
          src={sender?.avatarUrl || ""}
          alt=""
          style={{ width: 36, height: 36, borderRadius: 18, objectFit: "cover", marginRight: 8 }}
        />
      )}

      <div className={`msg ${isMe ? "me" : "other"} fade-in`} style={{ ...overflowStyle, position: "relative" }}>

        {isMe && (
          <MessageMenu
            msg={{ ...m, currentUserId }}
            onEdit={onEdit}
            onDeleteForMe={onDeleteForMe}
            onDeleteForAll={onDeleteForAll}
            openMenuId={openMenuId}
            setOpenMenuId={setOpenMenuId}
          />
        )}

        {/* Caso mensagem apagada */}
        {m.deletedForAll ? (
          <div style={{ fontStyle: "italic", color: "#666" }}>Mensagem excluída</div>
        ) : (
          <>
            {/* imagem */}
            {m.type === "image" && url && (
              <img src={url} style={{ width: "100%", borderRadius: 8 }} alt="img" />
            )}

            {/* vídeo */}
            {m.type === "video" && url && (
              <video src={url} controls style={{ width: "100%", borderRadius: 8 }} />
            )}

            {/* áudio */}
            {m.type === "audio" && url && <audio src={url} controls />}

            {/* GIF */}
            {m.type === "gif" && url && (
              <img src={url} style={{ width: "100%", borderRadius: 8 }} alt="gif" />
            )}

            {/* arquivo */}
            {m.type === "file" && url && (
              <a href={url} target="_blank" rel="noopener noreferrer">
                {url.split("/").pop()}
              </a>
            )}

            {/* TEXTO + EMOJIS + LINKS */}
            {(m.text && !m.deletedForAll) && (
              <div
                style={{ whiteSpace: "pre-wrap", marginTop: m.type !== "text" ? 8 : 0 }}
                dangerouslySetInnerHTML={{ __html: linkifyAndEmojify(m.text) }}
              />
            )}
          </>
        )}

        <div className="hora" style={{ display: "flex", justifyContent: "flex-end", fontSize: 11, gap: 6, marginTop: 6 }}>
          <span>{formatTime(m.createdAt)}</span>
          {m.edited && <span style={{ opacity: 0.6 }}>(editada)</span>}
        </div>
      </div>
    </div>
  );
}
